class ConsoleBuffer:
    """Ring buffer for console logs with configurable size."""

    def __init__(self, max_size: int = 1000):
        self.buffer = deque(maxlen=max_size)
        self.max_size = max_size

    def append(self, entry: dict):
        """Add entry to buffer."""
        self.buffer.append(entry)

    def get_all(self) -> list:
        """Get all entries and clear buffer."""
        entries = list(self.buffer)
        self.buffer.clear()
        return entries

    def __len__(self):
        return len(self.buffer)


async def http_get(host, port, path):
    """Simple async HTTP GET for CDP page discovery."""
    try:
        reader, writer = await asyncio.open_connection(host, port)
    except (OSError, ConnectionRefusedError):
        return None
    request = f'GET {path} HTTP/1.1\r\nHost: {host}:{port}\r\nConnection: close\r\n\r\n'
    writer.write(request.encode())
    await writer.drain()
    while True:
        line = await reader.readline()
        if line == b'\r\n' or not line:
            break
    body = await reader.read()
    writer.close()
    await writer.wait_closed()
    return body.decode()


class CDPClient:
    """Chrome DevTools Protocol client via WebSocket."""

    def __init__(self, cdp_port: int):
        self.cdp_port = cdp_port
        self.ws = None
        self.page_url = ''
        self.connected = False
        self._msg_id = 0
        self._pending = {}
        self._recv_task: Optional[asyncio.Task] = None
        self.event_buffer = deque(maxlen=2000)
        self.pending_requests = {}
        self.completed_requests = deque(maxlen=500)
        self._scripts = {}
        self._paused_frame_id = None
        self._perf_prev = {}  # previous Performance.metrics snapshot for deltas

    def _next_id(self):
        self._msg_id += 1
        return self._msg_id

    def _emit(self, event_type: str, data: dict):
        self.event_buffer.append((event_type, data))

    def drain_events(self):
        events = list(self.event_buffer)
        self.event_buffer.clear()
        return events

    def get_network_log(self):
        return list(self.completed_requests)

    def clear_network_log(self):
        self.completed_requests.clear()

    async def connect(self, origin: Optional[str] = None):
        for attempt in range(10):
            body = await http_get('localhost', self.cdp_port, '/json')
            if body is not None:
                break
            await asyncio.sleep(0.5)
        else:
            raise ConnectionError(
                f"No CDP endpoint at localhost:{self.cdp_port} "
                f"(chrome not ready after 5s wait)"
            )
        pages = json.loads(body)
        pages = [p for p in pages if p.get('type') == 'page']
        if not pages:
            raise ConnectionError("No debuggable pages found")
        page = pages[0]
        # Prefer the tab serving this project so eval/breakpoints target the
        # right document even when Chrome has multiple tabs open.
        if origin:
            for p in pages:
                if p.get('url', '').startswith(origin):
                    page = p
                    break
        ws_url = page['webSocketDebuggerUrl']
        self.page_url = page.get('url', '')

